894	/* Parse RIFF/WAVE header for duration in seconds (0 if not a valid WAV). */
895	static uint32_t music_wav_duration(const char *path)
896	{
897	    FILE *fp;
898	    uint8_t hdr[44];
899	    uint32_t byte_rate, data_len;
900	
901	    fp = fopen(path, "rb");
902	    if (fp == NULL) return 0;
903	
904	    if (fread(hdr, 1, sizeof(hdr), fp) != sizeof(hdr))
905	    {
906	        fclose(fp);
907	        return 0;
908	    }
909	    fclose(fp);
910	
911	    if (memcmp(hdr, "RIFF", 4) != 0 || memcmp(hdr + 8, "WAVE", 4) != 0)
912	        return 0;
913	
914	    memcpy(&byte_rate, hdr + 28, 4);
915	    memcpy(&data_len, hdr + 40, 4);
916	    if (byte_rate == 0) return 0;
917	
918	    return data_len / byte_rate;
919	}
