921	/* Scan /sdcard/music for supported audio files (mp3/flac/ogg/aac/wav).
922	 * Returns the number of tracks found. Call each time the playlist
923	 * overlay opens so newly copied songs appear. */
924	static uint32_t music_scan_tracks(void)
925	{
926	    DIR *dir;
927	    struct dirent *ent;
928	    const char *supported[] = { ".mp3", ".flac", ".ogg", ".aac", ".wav" };
929	    uint32_t count = 0;
930	
931	    dm_track_count = 0;
932	    dir = opendir(DM_MUSIC_DIR);
933	    if (dir == NULL)
934	        return 0;
935	
936	    while ((ent = readdir(dir)) != NULL && count < DM_MAX_TRACKS)
937	    {
938	        const char *dot = strrchr(ent->d_name, '.');
939	        int i, ok = 0;
940	
941	        if (dot == NULL || dot == ent->d_name)
942	            continue;
943	
944	        for (i = 0; i < 5; i++)
945	        {
946	            if (strcasecmp(dot, supported[i]) == 0)
947	            {
948	                ok = 1;
949	                break;
950	            }
951	        }
952	        if (!ok)
953	            continue;
954	
955	        snprintf(dm_tracks[count].path, sizeof(dm_tracks[count].path),
956	                 "%s/%s", DM_MUSIC_DIR, ent->d_name);
957	        snprintf(dm_tracks[count].title, sizeof(dm_tracks[count].title),
958	                 "%.*s", (int)(dot - ent->d_name), ent->d_name);
959	        dm_tracks[count].length = music_wav_duration(dm_tracks[count].path);
960	        count++;
961	    }
962	
963	    closedir(dir);
964	    dm_track_count = count;
965	    return count;
966	}
